{
  "name": "subscription-workflow-vue",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 127.0.0.1",
    "build": "vue-tsc --noEmit && vite build",
    "typecheck": "vue-tsc --noEmit"
  },
  "dependencies": {
    "@oods/component-styles": "0.1.0",
    "@oods/components-vue": "0.1.0",
    "vue": "3.5.42",
    "@vue/server-renderer": "3.5.42"
  },
  "devDependencies": {
    "@types/node": "20.19.21",
    "typescript": "5.9.3",
